css:
/* The rail itself is in normal flow: what sticks is the column that places it,
   because anything else in that column — a promo card under the list — has to
   travel with it rather than be slid over. */
.ss-toc{position:relative}
.ss-toc__l{font:700 var(--text-eyebrow)/1 var(--font-body);letter-spacing:.16em;text-transform:uppercase;color:var(--muted);margin:0 0 18px}
.ss-toc__list{display:flex;flex-direction:column;border-top:1px solid var(--line)}
.ss-toc__link{font-size:13px;font-weight:600;line-height:1.45;color:var(--body-text);border-bottom:1px solid var(--line);padding:11px 0;text-decoration:none}
.ss-toc__link:hover{color:var(--accent)}
/* The script adds .is-current; until it runs — and forever on the Design
   canvas, which runs no site JS — the rail is a plain list of links. */
.ss-toc__link.is-current{color:var(--accent);box-shadow:inset 3px 0 0 var(--accent);padding-left:10px}
@media (max-width:1100px){.ss-toc__link{padding:13px 0}}
